// ================= общий мозг =================
// история чата с паузой («стоп» — 30 дней) живёт не меньше, чем сама пауза
const histTtl = prof => Math.max(7 * 86400, prof && prof.pausedUntil > Date.now() ? Math.ceil((prof.pausedUntil - Date.now()) / 1000) + 86400 : 0);
