    const all = await loadCfgs(env);
    if (!Object.hasOwn(all, id)) return json({ error: "Такого бота нет." }, 404);
    if (String(b.confirm || "") !== id) return json({ error: "Для удаления введите идентификатор бота." }, 400);
    delete all[id];
